<script lang="ts">
 import { invoke } from '@tauri-apps/api/core';
 import { estimateTotalCost } from './lib/kwantflow/estimate-calculation.js';
 import { buildStepQuote, parseStepInventory } from './lib/kwantflow/step-quote.js';
 import { calculateWeld } from './lib/welding.mjs';
 import { estimateCnc, estimateCut, estimateBending, estimateFabrication } from './lib/estimate.mjs';
 import { massFromVolume } from './lib/geometry.mjs';
 let tab=$state('Nowa wycena');
 let stepData=$state<any>(null);
 let assemblyMinutes=$state(1367), weldLengthMm=$state(54960), weldThroat=$state(5), weldDeposition=$state(2.5), weldArcFraction=$state(35);
 let fabrication=$derived.by(()=>{try{return estimateFabrication({ratePerHour:rate,assembly:{operations:[{name:'Montaż według technologii',minutesEach:assemblyMinutes}]},welding:{joints:[{lengthMm:weldLengthMm,throatMm:weldThroat}],depositionKgHour:weldDeposition,arcOnFraction:weldArcFraction/100,setupMin:60},cutting:{contourMm,feedMmMin:cutFeed,pierces},cnc:{removedCm3,removalCm3Min,setupMin:cncSetup}})}catch{return null}});
 let stepPath=$state(''), stepResult=$state(''), stepError=$state(''), stepBusy=$state(false);
 async function analyzeStepFile() {
   stepBusy=true; stepError=''; stepResult=''; stepData=null;
   try { stepResult=await invoke<string>('analyze_step',{path:stepPath.trim()}); stepData=parseStepInventory(stepResult); }
   catch(e) { stepError=String(e); }
   finally { stepBusy=false; }
 }
 let volumeMm3=$state(1000000),densityKgM3=$state(7850),partQuantity=$state(1);
 let partMass=$derived.by(()=>{try{return massFromVolume(volumeMm3,densityKgM3)}catch{return null}});
 let removedCm3=$state(100), removalCm3Min=$state(10), cncSetup=$state(20), contourMm=$state(3000), cutFeed=$state(1500), pierces=$state(10), bends=$state(4), bendSeconds=$state(30), rate=$state(388);
 // DS Estimate calculates operation time; Kwantflow sums the actual costing components.
 let cncOperations=$derived.by(()=>{
  try {
   if (![cncSetup,removedCm3,removalCm3Min,partQuantity,rate].every(Number.isFinite) || removalCm3Min<=0 || partQuantity<1 || !Number.isInteger(partQuantity) || cncSetup<0 || removedCm3<0 || rate<0) return null;
   const estimate={takeoff_items:[
    {quantity:1,cost_components:[{quantity:cncSetup/60,unit_rate:rate,category:'labour'}]},
    {quantity:partQuantity,cost_components:[{quantity:(removedCm3/removalCm3Min)/60,unit_rate:rate,category:'equipment'}]}
   ]};
   return {totalCostPln:estimateTotalCost(estimate)};
  } catch {return null}
 });
 let cnc=$derived.by(()=>{try{return estimateCnc({removedCm3,removalCm3Min,setupMin:cncSetup,ratePerHour:rate})}catch{return null}});
 let cutting=$derived.by(()=>{try{return estimateCut({contourMm,feedMmMin:cutFeed,pierces,ratePerHour:rate})}catch{return null}});
 let bending=$derived.by(()=>{try{return estimateBending({bends,secondsPerBend:bendSeconds,ratePerHour:rate})}catch{return null}}); let lengthM=$state(8), throatMm=$state(4), depositionKgH=$state(2), arcPercent=$state(35), setupMin=$state(20);
 let result=$derived.by(()=>{try{return calculateWeld({lengthM,throatMm,depositionKgH,arcFactor:arcPercent/100,setupMin})}catch{return null}});
 let materialRatePlnKg=$state(0), includeManualRouting=$state(false), generalMarkupPercent=$state(0), useCategoryMarkups=$state(false), materialMarkupPercent=$state(0), labourMarkupPercent=$state(0), equipmentMarkupPercent=$state(0);
 let stepQuote=$derived.by(()=>{if(!stepData || materialRatePlnKg<=0)return null;try{return buildStepQuote(stepData,{materialRatePlnKg,ratePlnHour:rate,markup:{generalPercent:generalMarkupPercent,materialPercent:useCategoryMarkups?materialMarkupPercent:null,labourPercent:useCategoryMarkups?labourMarkupPercent:null,equipmentPercent:useCategoryMarkups?equipmentMarkupPercent:null},routing:includeManualRouting?{assemblyMin:assemblyMinutes,weldingMin:fabrication?.steps.welding?.totalMin??0,cuttingMin:fabrication?.steps.cutting?.totalMin??0,cncMin:fabrication?.steps.cnc?.totalMin??0}:{}})}catch{return null}});
 const tabs=['Konstrukcja spawana','Nowa wycena','Masa i geometria','Frezowanie','Cięcie','Gięcie','Spawanie','Wyniki','Podgląd 3D','Ustawienia'];
 const fmt=(n:number)=>n.toLocaleString('pl-PL',{maximumFractionDigits:2,minimumFractionDigits:2});
</script>
<svelte:head><meta name="theme-color" content="#11151c"/></svelte:head>
<div class="app"><aside><div class="brand"><span class="mark">DS</span><div><b>DS Estimate</b><small>Desktop · 2.0 alpha</small></div></div><nav>{#each tabs as t}<button class:active={tab===t} onclick={()=>tab=t}>{t}</button>{/each}</nav><div class="bottom">Svelte 5 · Tauri 2<br/>Offline</div></aside><main><header><div><small>PROJEKT / WYCENA</small><h1>{tab}</h1></div><span class="status">● Prototyp</span></header>{#if tab==='Konstrukcja spawana'}<section class="panel"><h2>Technologia wykonania — wycena szczegółowa</h2><p>STEP dostarcza geometrię i masę. Czas montażu i długość spoin wymagają na razie danych technologicznych; nie są automatycznie wykrywane z modelu.</p><div class="fields"><label>Montaż i sczepianie [min]<input type="number" min="0" bind:value={assemblyMinutes}/></label><label>Długość spoin [mm]<input type="number" min="0" bind:value={weldLengthMm}/></label><label>Gardziel spoiny a [mm]<input type="number" min="0.1" bind:value={weldThroat}/></label><label>Wydajność stapiania [kg/h]<input type="number" min="0.1" bind:value={weldDeposition}/></label><label>Udział czasu łuku [%]<input type="number" min="1" max="100" bind:value={weldArcFraction}/></label><label>Stawka [zł/h]<input type="number" min="0" bind:value={rate}/></label></div>{#if stepData}<p>Wczytany STEP: {stepData.count} brył, masa {fmt(stepData.totalMassKg)} kg. Te wartości nie wyznaczają automatycznie długości spoin.</p>{/if}</section>{#if fabrication}<div class="stats"><article><small>Montaż</small><strong>{fmt(fabrication.steps.assembly.totalMin/60)} <em>h</em></strong></article><article><small>Spawanie</small><strong>{fmt(fabrication.steps.welding.totalMin/60)} <em>h</em></strong></article><article><small>Całość operacji</small><strong>{fmt(fabrication.totalMin/60)} <em>h</em></strong></article><article><small>Koszt operacji</small><strong>{fmt(fabrication.totalCost)} <em>zł</em></strong></article></div>{/if}{:else if tab==='Nowa wycena'}<section class="panel"><h2>Import STEP — OCCT</h2><p>Wskaż pełną ścieżkę pliku STEP. Analiza uruchamia dołączony silnik CAD i zwraca wynik JSON.</p><label for="step-path">Ścieżka pliku STEP</label><input id="step-path" type="text" bind:value={stepPath} placeholder="C:\\modele\\zlozenie.step" /><button onclick={analyzeStepFile} disabled={stepBusy || !stepPath.trim()}>{stepBusy?'Analizowanie…':'Analizuj STEP'}</button>{#if stepError}<p role="alert">Błąd: {stepError}</p>{/if}{#if stepData}<h2>Przedmiar STEP → Kwantflow</h2><p>Rozpoznano {stepData.count} brył w {stepData.groups?.length ?? 0} grupach. Masa {fmt(stepData.totalMassKg)} kg. Czas operacji pochodzi z zakładki Konstrukcja spawana, nie z automatycznego rozpoznawania spoin.</p><div class="fields"><label>Cena materiału [zł/kg] — wymagana<input type="number" min="0.01" step="0.01" bind:value={materialRatePlnKg}/></label><label>Stawka roboczogodziny [zł/h]<input type="number" min="0.01" bind:value={rate}/></label></div><p><label><input type="checkbox" bind:checked={useCategoryMarkups}/> Indywidualne marże kategorii (wyłączone = marża ogólna)</label></p><div class="fields"><label>Marża ogólna [%]<input type="number" min="-100" bind:value={generalMarkupPercent}/></label><label>Marża materiał [%]<input type="number" min="-100" bind:value={materialMarkupPercent}/></label><label>Marża robocizna [%]<input type="number" min="-100" bind:value={labourMarkupPercent}/></label><label>Marża maszyny [%]<input type="number" min="-100" bind:value={equipmentMarkupPercent}/></label></div><p>Marże kategorii są liczone przez oryginalną funkcję Kwantflow. Wartość 0% oznacza brak narzutu w danej kategorii.</p><p><label><input type="checkbox" bind:checked={includeManualRouting}/> Dodaj ręczną technologię z zakładki Konstrukcja spawana (domyślnie wyłączone; wartości testowe nie opisują wczytanego STEP)</label></p>{#if stepQuote}<div class="stats"><article><small>Materiał</small><strong>{fmt(stepQuote.materialCostPln)} <em>zł</em></strong></article><article><small>Operacje</small><strong>{fmt(stepQuote.routingCostPln)} <em>zł</em></strong></article><article><small>Łączny koszt Kwantflow</small><strong>{fmt(stepQuote.totalCostPln)} <em>zł</em></strong></article><article><small>Cena sprzedaży Kwantflow</small><strong>{fmt(stepQuote.sellingPricePln)} <em>zł</em></strong></article><article><small>Narzut kwotowy</small><strong>{fmt(stepQuote.markupAmountPln)} <em>zł</em></strong></article></div><p>Wynik bez marży, odpadów i niewprowadzonych kosztów. Ilości i masa pochodzą z OCCT; normy technologiczne i stawki wymagają weryfikacji.</p>{:else}<p>Wprowadź dodatnią cenę materiału i poprawne parametry technologii, aby utworzyć kosztorys. Brak ceny nie oznacza kosztu zerowego.</p>{/if}<details><summary>Surowy raport OCCT</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{stepResult}</pre></details>{/if}</section>{/if}{#if tab==='Masa i geometria'}<section class="panel"><h2>Masa części z objętości B-Rep</h2><p>Przeliczenie masy na podstawie objętości podanej przez silnik CAD. Automatyczny import STEP i weryfikacja identyczności brył są w przygotowaniu.</p><div class="fields"><label>Objętość [mm³]<input type="number" min="0" bind:value={volumeMm3}/></label><label>Gęstość [kg/m³]<input type="number" min="0" bind:value={densityKgM3}/></label><label>Ilość sztuk<input type="number" min="1" step="1" bind:value={partQuantity}/></label></div></section><div class="stats"><article><small>Masa jednostkowa</small><strong>{partMass!==null?fmt(partMass):'—'} <em>kg</em></strong></article><article><small>Masa całkowita</small><strong>{partMass!==null&&Number.isInteger(partQuantity)&&partQuantity>=1?fmt(partMass*partQuantity):'—'} <em>kg</em></strong></article></div>{:else if tab==='Frezowanie'}<section class="panel"><h2>Szacowanie frezowania CNC</h2><p>Czas obróbki szacuje DS Estimate; koszt przygotowania i obróbki sumuje moduł Kwantflow. Import STEP i CAM nie są jeszcze podłączone.</p><div class="fields"><label>Objętość do usunięcia [cm³]<input type="number" min="0" bind:value={removedCm3}/></label><label>Wydajność usuwania [cm³/min]<input type="number" min="0.01" bind:value={removalCm3Min}/></label><label>Przygotowanie [min]<input type="number" min="0" bind:value={cncSetup}/></label><label>Stawka [zł/h]<input type="number" min="0" bind:value={rate}/></label></div></section><div class="stats"><article><small>Czas skrawania</small><strong>{cnc?fmt(cnc.millingMin):'—'} <em>min</em></strong></article><article><small>Czas całkowity</small><strong>{cnc?fmt(cnc.totalMin):'—'} <em>min</em></strong></article><article><small>Koszt</small><strong>{cncOperations?fmt(cncOperations.totalCostPln):'—'} <em>zł</em></strong></article></div>{:else if tab==='Cięcie'}<section class="panel"><h2>Szacowanie cięcia</h2><p>Długość konturu, przebicia i czas przygotowania; nesting i DXF jeszcze niepodłączone.</p><div class="fields"><label>Długość konturu [mm]<input type="number" min="0" bind:value={contourMm}/></label><label>Prędkość cięcia [mm/min]<input type="number" min="0.01" bind:value={cutFeed}/></label><label>Liczba przebić<input type="number" min="0" bind:value={pierces}/></label><label>Stawka [zł/h]<input type="number" min="0" bind:value={rate}/></label></div></section><div class="stats"><article><small>Czas cięcia i przygotowania</small><strong>{cutting?fmt(cutting.totalMin):'—'} <em>min</em></strong></article><article><small>Koszt</small><strong>{cutting?fmt(cutting.cost):'—'} <em>zł</em></strong></article></div>{:else if tab==='Gięcie'}<section class="panel"><h2>Szacowanie gięcia</h2><p>Czas operacyjny i przygotowanie; rozwijanie blach nie jest jeszcze podłączone.</p><div class="fields"><label>Liczba gięć<input type="number" min="0" bind:value={bends}/></label><label>Czas jednego gięcia [s]<input type="number" min="0" bind:value={bendSeconds}/></label><label>Stawka [zł/h]<input type="number" min="0" bind:value={rate}/></label></div></section><div class="stats"><article><small>Czas całkowity</small><strong>{bending?fmt(bending.totalMin):'—'} <em>min</em></strong></article><article><small>Koszt</small><strong>{bending?fmt(bending.cost):'—'} <em>zł</em></strong></article></div>{:else if tab==='Spawanie'}<section class="panel"><h2>Kalkulator czasu spawania</h2><p>Spoiny pachwinowe o równych ramionach. Wyniki szacunkowe.</p><div class="fields"><label>Długość spoin [m]<input type="number" min="0" bind:value={lengthM}/></label><label>Gardziel a [mm]<input type="number" min="0" bind:value={throatMm}/></label><label>Wydajność stapiania [kg/h]<input type="number" min="0.01" step="0.1" bind:value={depositionKgH}/></label><label>Udział czasu łuku [%]<input type="number" min="1" max="100" bind:value={arcPercent}/></label><label>Przygotowanie [min]<input type="number" min="0" bind:value={setupMin}/></label></div></section><div class="stats"><article><small>Masa spoiny</small><strong>{result?fmt(result.massKg):'—'} <em>kg</em></strong></article><article><small>Czas łuku</small><strong>{result?fmt(result.arcMinutes):'—'} <em>min</em></strong></article><article><small>Czas całkowity</small><strong>{result?fmt(result.totalMinutes/60):'—'} <em>h</em></strong></article></div>{:else}<section class="panel empty"><h2>{tab}</h2><p>Moduł w przygotowaniu. Analiza STEP/PDF/DXF/DWG i wykrywanie spoin nie są jeszcze zaimplementowane.</p></section>{/if}<footer>Wyniki wymagają weryfikacji technologicznej.</footer></main></div>
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#0d1117;color:#e8edf4;font:14px system-ui,'Segoe UI',sans-serif}.app{min-height:100vh;display:flex}aside{width:230px;flex-shrink:0;background:#121820;border-right:1px solid #26303d;display:flex;flex-direction:column;padding:25px 14px}.brand{display:flex;align-items:center;gap:12px;padding:0 10px 36px}.brand b{font-size:17px}.brand small{display:block;color:#8b98a9;margin-top:4px}.mark{background:#e9eef6;color:#121820;border-radius:10px;padding:11px;font-weight:800}nav{display:grid;gap:5px}nav button{border:0;text-align:left;color:#aab6c6;background:transparent;border-radius:8px;padding:13px;cursor:pointer;font:inherit}nav button:hover{background:#202b38}nav button.active{background:#253244;color:white}.bottom{margin-top:auto;color:#708093;padding:15px 10px;line-height:1.8}main{flex:1;min-width:0;padding:36px;max-width:1500px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:32px;gap:12px}small{color:#96a4b6}header small{letter-spacing:1.5px;font-size:11px}h1{font-size:30px;margin:7px 0 0;font-weight:650}.status{font-size:12px;color:#91c4a6;border:1px solid #29463c;border-radius:30px;padding:8px 12px}.panel{background:#161e28;border:1px solid #2a3544;border-radius:13px;padding:28px;max-width:1000px}h2{margin:0 0 9px;font-size:19px}.panel p{color:#9ba8b8;margin:0 0 28px;line-height:1.6}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.fields label{color:#bdc7d5;font-size:13px;display:grid;gap:9px}.fields input{background:#101721;color:white;border:1px solid #364456;border-radius:8px;padding:12px;font:inherit;width:100%;min-width:0}.fields input:focus{outline:2px solid #718cad}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:18px;max-width:1000px}.stats article{background:#161e28;border:1px solid #2a3544;border-radius:12px;padding:23px;min-width:0}.stats small{display:block;margin-bottom:13px}.stats strong{font-size:27px;overflow-wrap:anywhere}.stats em{font-size:14px;font-style:normal;color:#9aa9ba}footer{margin-top:30px;color:#7d8b9e;font-size:12px}.empty{min-height:200px}@media(max-width:800px){aside{width:170px}main{padding:20px}.stats{grid-template-columns:1fr}.fields{grid-template-columns:1fr}}@media(max-width:550px){.app{display:block}aside{width:auto;padding:12px}.brand{padding:5px 10px 10px}nav{display:flex;overflow:auto}.bottom{display:none}nav button{white-space:nowrap;padding:10px}header{align-items:flex-start;flex-direction:column}.panel{padding:18px}}
</style>